{-| @Backend.Runtime.Host.Concurrent — cells, locks, channels and threads behind their tokens, as `Pudu.Eval.Concurrent` answers them. A held value is a box of one member; the function that releases the box names its type. -}
module Pudu.Backend.Runtime.Host.Concurrent (hostConcurrentParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostConcurrentParts :: [(Text, [Text], [Text])]
hostConcurrentParts =
  [ ("host_cell", ["host_objects", "host_gate"],
      [ "typedef void (*pudu_host_drop)(pudu_box *);"
      , "typedef struct { pudu_box *held; pudu_host_drop drop; } pudu_host_cell;"
      ])
  , ("host_cell_open", ["host_cell", "kernel_int", "memory_failure"],
      [ "static pudu_int pudu_host_cell_open(pudu_box *value, pudu_host_drop drop) {"
      , "  pudu_host_cell *cell = malloc(sizeof *cell);"
      , "  if (cell == NULL) pudu_memory_failure();"
      , "  cell->held = pudu_box_retain(value);"
      , "  cell->drop = drop;"
      , "  pudu_host_yield();"
      , "  return pudu_kernel_int(pudu_host_register(4, cell));"
      , "}"
      ])
  , ("host_cell_get", ["host_cell", "host_done", "host_fail"],
      [ "static pudu_box *pudu_host_cell_get(pudu_int token, pudu_host_drop drop) {"
      , "  pudu_host_cell *cell;"
      , "  pudu_host_yield();"
      , "  cell = pudu_host_find(4, token);"
      , "  if (cell == NULL) { pudu_host_fail(\"no such cell\"); return NULL; }"
      , "  if (cell->drop != drop) { pudu_host_fail(\"the cell holds a value of another type\"); return NULL; }"
      , "  pudu_host_done(0);"
      , "  return pudu_box_retain(cell->held);"
      , "}"
      ])
  , ("host_cell_swap", ["host_cell", "host_done", "host_fail"],
      [ "/* The value held before; the cell takes the new one, whatever its type. */"
      , "static pudu_box *pudu_host_cell_swap(pudu_int token, pudu_box *value, pudu_host_drop drop) {"
      , "  pudu_host_cell *cell;"
      , "  pudu_box *previous;"
      , "  pudu_host_yield();"
      , "  cell = pudu_host_find(4, token);"
      , "  if (cell == NULL) { pudu_host_fail(\"no such cell\"); return NULL; }"
      , "  if (cell->drop != drop) { pudu_host_fail(\"the cell holds a value of another type\"); return NULL; }"
      , "  previous = cell->held;"
      , "  cell->held = pudu_box_retain(value);"
      , "  pudu_host_changed();"
      , "  pudu_host_done(0);"
      , "  return previous;"
      , "}"
      ])
  , ("host_cell_dispose", ["host_cell", "host_done", "host_fail"],
      [ "static int pudu_host_cell_dispose(pudu_int token) {"
      , "  pudu_host_cell *cell = pudu_host_find(4, token);"
      , "  if (cell == NULL) { pudu_host_fail(\"no such cell\"); return 0; }"
      , "  cell->drop(cell->held);"
      , "  free(cell);"
      , "  pudu_host_forget(token);"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_self", ["host_optional"],
      [ "/* Which thread this is: zero for the one the program started on. */"
      , "PUDU_OPTIONAL static _Thread_local uint64_t pudu_host_self = 0;"
      ])
  , ("host_mutex", ["host_objects", "host_gate", "host_self"],
      [ "typedef struct { int held; uint64_t owner; } pudu_host_mutex;"
      ])
  , ("host_mutex_open", ["host_mutex", "kernel_int", "memory_failure"],
      [ "static pudu_int pudu_host_mutex_open(void) {"
      , "  pudu_host_mutex *lock = malloc(sizeof *lock);"
      , "  if (lock == NULL) pudu_memory_failure();"
      , "  lock->held = 0;"
      , "  lock->owner = 0;"
      , "  return pudu_kernel_int(pudu_host_register(3, lock));"
      , "}"
      ])
  , ("host_mutex_take", ["host_optional", "host_mutex", "host_done", "host_fail"],
      [ "/* One try: 1 taken, 0 held by another thread, -1 refused. */"
      , "PUDU_OPTIONAL static inline int pudu_host_mutex_take(pudu_int token) {"
      , "  pudu_host_mutex *lock = pudu_host_find(3, token);"
      , "  if (lock == NULL) { pudu_host_fail(\"no such lock\"); return -1; }"
      , "  if (!lock->held) { lock->held = 1; lock->owner = pudu_host_self; pudu_host_done(0); return 1; }"
      , "  if (lock->owner == pudu_host_self) { pudu_host_fail(\"the lock is already owned by this thread\"); return -1; }"
      , "  return 0;"
      , "}"
      ])
  , ("host_mutex_acquire", ["host_mutex_take"],
      [ "static int pudu_host_mutex_acquire(pudu_int token) {"
      , "  pudu_host_yield();"
      , "  while (pudu_host_mutex_take(token) == 0) (void)pudu_host_wait(NULL);"
      , "  return 1;"
      , "}"
      ])
  , ("host_mutex_acquire_within", ["host_mutex_take", "kernel_signed"],
      [ "/* Whether the lock was taken before the time ran out. */"
      , "static int pudu_host_mutex_acquire_within(pudu_int token, pudu_int millis) {"
      , "  int64_t wanted = pudu_kernel_signed(millis.bits);"
      , "  struct timespec until;"
      , "  int taken;"
      , "  if (wanted < 0 || wanted > 3600000) { pudu_host_fail(\"invalid mutex wait\"); return 0; }"
      , "  if (pudu_kernel_signed(token.bits) < 1) { pudu_host_fail(\"no such lock\"); return 0; }"
      , "  pudu_host_yield();"
      , "  taken = pudu_host_mutex_take(token);"
      , "  if (taken != 0 || wanted == 0) { if (taken == 0) pudu_host_done(0); return taken == 1; }"
      , "  until = pudu_host_until(wanted);"
      , "  for (;;) {"
      , "    int moved = pudu_host_wait(&until);"
      , "    taken = pudu_host_mutex_take(token);"
      , "    if (taken != 0) return taken == 1;"
      , "    if (!moved) { pudu_host_done(0); return 0; }"
      , "  }"
      , "}"
      ])
  , ("host_mutex_release", ["host_mutex", "host_done", "host_fail"],
      [ "static int pudu_host_mutex_release(pudu_int token) {"
      , "  pudu_host_mutex *lock = pudu_host_find(3, token);"
      , "  if (lock == NULL) { pudu_host_fail(\"no such lock\"); return 0; }"
      , "  if (!lock->held) { pudu_host_fail(\"the lock is not held\"); return 0; }"
      , "  if (lock->owner != pudu_host_self) { pudu_host_fail(\"the lock is owned by another thread\"); return 0; }"
      , "  lock->held = 0;"
      , "  pudu_host_changed();"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_mutex_dispose", ["host_mutex", "host_done", "host_fail"],
      [ "static int pudu_host_mutex_dispose(pudu_int token) {"
      , "  pudu_host_mutex *lock = pudu_host_find(3, token);"
      , "  if (lock == NULL) { pudu_host_fail(\"no such lock\"); return 0; }"
      , "  if (lock->held) { pudu_host_fail(\"the lock is still held\"); return 0; }"
      , "  free(lock);"
      , "  pudu_host_forget(token);"
      , "  pudu_host_changed();"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_channel", ["host_objects", "host_gate"],
      [ "typedef void (*pudu_host_item_drop)(pudu_box *);"
      , "typedef struct { pudu_box **items; size_t first, count, room, limit; int closed; pudu_host_item_drop drop; } pudu_host_channel;"
      ])
  , ("host_channel_open", ["host_channel", "kernel_int", "kernel_signed", "memory_failure"],
      [ "static pudu_int pudu_host_channel_open(pudu_int limit) {"
      , "  int64_t wanted = pudu_kernel_signed(limit.bits);"
      , "  pudu_host_channel *channel = malloc(sizeof *channel);"
      , "  if (channel == NULL) pudu_memory_failure();"
      , "  channel->items = NULL;"
      , "  channel->first = channel->count = channel->room = 0;"
      , "  channel->limit = wanted < 1 ? 1 : (size_t)wanted;"
      , "  channel->closed = 0;"
      , "  channel->drop = NULL;"
      , "  return pudu_kernel_int(pudu_host_register(2, channel));"
      , "}"
      ])
  , ("host_channel_push", ["host_channel", "host_done", "host_fail", "memory_failure"],
      [ "/* Waits for room; the items keep the order they were sent in. */"
      , "static int pudu_host_channel_push(pudu_int token, pudu_box *value, pudu_host_item_drop drop) {"
      , "  pudu_host_yield();"
      , "  for (;;) {"
      , "    pudu_host_channel *channel = pudu_host_find(2, token);"
      , "    if (channel == NULL) { pudu_host_fail(\"no such channel\"); return 0; }"
      , "    if (channel->closed) { pudu_host_fail(\"the channel is closed\"); return 0; }"
      , "    if (channel->count != 0 && channel->drop != drop) { pudu_host_fail(\"the channel holds values of another type\"); return 0; }"
      , "    if (channel->count < channel->limit) {"
      , "      if (channel->count == channel->room) {"
      , "        size_t room = channel->room < 4 ? 4 : channel->room * 2;"
      , "        pudu_box **items = malloc(room * sizeof *items);"
      , "        if (items == NULL) pudu_memory_failure();"
      , "        for (size_t index = 0; index < channel->count; ++index) items[index] = channel->items[(channel->first + index) % channel->room];"
      , "        free(channel->items);"
      , "        channel->items = items;"
      , "        channel->first = 0;"
      , "        channel->room = room;"
      , "      }"
      , "      channel->items[(channel->first + channel->count) % channel->room] = pudu_box_retain(value);"
      , "      channel->count += 1;"
      , "      channel->drop = drop;"
      , "      pudu_host_changed();"
      , "      pudu_host_done(0);"
      , "      return 1;"
      , "    }"
      , "    (void)pudu_host_wait(NULL);"
      , "  }"
      , "}"
      ])
  , ("host_channel_take", ["host_optional", "host_channel", "host_done", "host_fail"],
      [ "/* One try: the first item (state 0), nothing more to come (3), nothing yet"
      , "   (2), or a refusal (1). */"
      , "PUDU_OPTIONAL static inline pudu_box *pudu_host_channel_take(pudu_int token, pudu_host_item_drop drop) {"
      , "  pudu_host_channel *channel = pudu_host_find(2, token);"
      , "  pudu_box *item;"
      , "  if (channel == NULL) { pudu_host_fail(\"no such channel\"); return NULL; }"
      , "  if (channel->count == 0) { pudu_host_done(channel->closed ? 3 : 2); return NULL; }"
      , "  if (channel->drop != drop) { pudu_host_fail(\"the channel holds values of another type\"); return NULL; }"
      , "  item = channel->items[channel->first];"
      , "  channel->first = (channel->first + 1) % channel->room;"
      , "  channel->count -= 1;"
      , "  if (channel->count == 0) { free(channel->items); channel->items = NULL; channel->first = channel->room = 0; }"
      , "  pudu_host_changed();"
      , "  pudu_host_done(0);"
      , "  return item;"
      , "}"
      ])
  , ("host_channel_pull", ["host_channel_take"],
      [ "/* Waits for an item; state 2 once the channel is closed and empty. */"
      , "static pudu_box *pudu_host_channel_pull(pudu_int token, pudu_host_item_drop drop) {"
      , "  pudu_host_yield();"
      , "  for (;;) {"
      , "    pudu_box *item = pudu_host_channel_take(token, drop);"
      , "    if (pudu_host_status == 3) pudu_host_status = 2;"
      , "    else if (pudu_host_status == 2) { (void)pudu_host_wait(NULL); continue; }"
      , "    return item;"
      , "  }"
      , "}"
      ])
  , ("host_channel_pull_within", ["host_channel_take", "kernel_signed"],
      [ "/* The same with a limit on the wait: state 2 when the time ran out, 3 when"
      , "   the channel is closed and empty. */"
      , "static pudu_box *pudu_host_channel_pull_within(pudu_int token, pudu_int millis, pudu_host_item_drop drop) {"
      , "  int64_t wanted = pudu_kernel_signed(millis.bits);"
      , "  struct timespec until;"
      , "  pudu_box *item;"
      , "  if (wanted < 0 || wanted > INT64_MAX / 1000) { pudu_host_fail(\"invalid channel wait\"); return NULL; }"
      , "  if (pudu_kernel_signed(token.bits) < 1) { pudu_host_fail(\"no such channel\"); return NULL; }"
      , "  pudu_host_yield();"
      , "  item = pudu_host_channel_take(token, drop);"
      , "  if (pudu_host_status != 2 || wanted == 0) return item;"
      , "  until = pudu_host_until(wanted);"
      , "  for (;;) {"
      , "    int moved = pudu_host_wait(&until);"
      , "    item = pudu_host_channel_take(token, drop);"
      , "    if (pudu_host_status != 2 || !moved) return item;"
      , "  }"
      , "}"
      ])
  , ("host_channel_waiting", ["host_channel", "host_done", "host_fail"],
      [ "static pudu_int pudu_host_channel_waiting(pudu_int token) {"
      , "  pudu_host_channel *channel = pudu_host_find(2, token);"
      , "  if (channel == NULL) { pudu_host_fail(\"no such channel\"); return pudu_kernel_int(0); }"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int((int64_t)channel->count);"
      , "}"
      ])
  , ("host_channel_finish", ["host_channel", "host_done", "host_fail"],
      [ "static int pudu_host_channel_finish(pudu_int token) {"
      , "  pudu_host_channel *channel = pudu_host_find(2, token);"
      , "  if (channel == NULL) { pudu_host_fail(\"no such channel\"); return 0; }"
      , "  channel->closed = 1;"
      , "  pudu_host_changed();"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_thread", ["host_objects", "host_gate", "host_self"],
      [ "typedef struct { pudu_box *action; void (*drop)(pudu_box *); size_t depth; uint64_t self; int finished, failed; pudu_text problem; } pudu_host_thread;"
      ])
  , ("host_thread_spawn", ["host_optional", "host_thread", "host_done", "kernel_int", "text_copy", "memory_failure", "cleanup"],
      [ "#include <setjmp.h>"
      , "PUDU_OPTIONAL static pudu_cell pudu_run_closure(pudu_box *closure, size_t depth);"
      , "PUDU_OPTIONAL static _Thread_local size_t pudu_frame_depth;"
      , "PUDU_OPTIONAL static _Thread_local jmp_buf *pudu_host_escape = NULL;"
      , "PUDU_OPTIONAL static _Thread_local pudu_text pudu_host_problem;"
      , "/* A failure on a started thread ends that thread, which keeps what it said"
      , "   for whoever joins it. */"
      , "static void pudu_host_trap(const char *message, size_t length, void *owned_payload) {"
      , "  if (pudu_host_escape == NULL) return;"
      , "  pudu_host_problem = pudu_text_copy(message, length);"
      , "  free(owned_payload);"
      , "  if (pudu_cleanup_hook != NULL) pudu_cleanup_hook();"
      , "  longjmp(*pudu_host_escape, 1);"
      , "}"
      , "static void *pudu_host_thread_run(void *given) {"
      , "  pudu_host_thread *thread = given;"
      , "  jmp_buf escape;"
      , "  pudu_host_enter();"
      , "  pudu_host_self = thread->self;"
      , "  pudu_host_escape = &escape;"
      , "  if (setjmp(escape) == 0) (void)pudu_run_closure(thread->action, thread->depth);"
      , "  else { thread->failed = 1; thread->problem = pudu_host_problem; }"
      , "  pudu_host_escape = NULL;"
      , "  thread->drop(thread->action);"
      , "  thread->finished = 1;"
      , "  pudu_host_changed();"
      , "  pudu_host_leave();"
      , "  return NULL;"
      , "}"
      , "static pudu_int pudu_host_thread_spawn(pudu_box *action, void (*drop)(pudu_box *)) {"
      , "  pudu_host_thread *thread = malloc(sizeof *thread);"
      , "  pthread_t started;"
      , "  int64_t token;"
      , "  if (thread == NULL) pudu_memory_failure();"
      , "  thread->action = pudu_box_retain(action);"
      , "  thread->drop = drop;"
      , "  thread->depth = pudu_frame_depth;"
      , "  thread->finished = thread->failed = 0;"
      , "  token = pudu_host_register(1, thread);"
      , "  thread->self = (uint64_t)token;"
      , "  pudu_gate_shared = 1;"
      , "  pudu_trap_hook = pudu_host_trap;"
      , "  if (pthread_create(&started, NULL, pudu_host_thread_run, thread) != 0) pudu_memory_failure();"
      , "  (void)pthread_detach(started);"
      , "  pudu_host_done(0);"
      , "  return pudu_kernel_int(token);"
      , "}"
      ])
  , ("host_thread_join", ["host_thread", "host_done", "host_fail", "text_retain"],
      [ "/* Waits for the thread and says what it said, each time it is asked. */"
      , "static int pudu_host_thread_join(pudu_int token) {"
      , "  pudu_host_thread *thread;"
      , "  pudu_host_yield();"
      , "  for (;;) {"
      , "    thread = pudu_host_find(1, token);"
      , "    if (thread == NULL) { pudu_host_fail(\"no such thread\"); return 0; }"
      , "    if (thread->finished) break;"
      , "    (void)pudu_host_wait(NULL);"
      , "  }"
      , "  if (thread->failed) {"
      , "    pudu_text_release(pudu_host_said);"
      , "    pudu_host_said = pudu_text_retain(thread->problem);"
      , "    pudu_host_status = 1;"
      , "    return 0;"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  , ("host_thread_forget", ["host_thread", "host_done", "host_fail"],
      [ "static int pudu_host_thread_forget(pudu_int token) {"
      , "  pudu_host_thread *thread = pudu_host_find(1, token);"
      , "  if (thread == NULL) { pudu_host_fail(\"no such thread\"); return 0; }"
      , "  if (!thread->finished) { pudu_host_fail(\"the thread is still running\"); return 0; }"
      , "  if (thread->failed) pudu_text_release(thread->problem);"
      , "  free(thread);"
      , "  pudu_host_forget(token);"
      , "  pudu_host_done(0);"
      , "  return 1;"
      , "}"
      ])
  ]
